svg.script:
(function() {
  var SVG_NS   = 'http://www.w3.org/2000/svg';
  var XLINK_NS = 'http://www.w3.org/1999/xlink';
  var ANIME_URL = 'https://cdn.jsdelivr.net/npm/animejs@4/dist/bundles/anime.umd.min.js';
  var EDGE_SEL = 'path.flowchart-link, path.messageLine0, path.messageLine1, path.relation, .edgePaths > path';
  var NODE_SEL = 'g.node, g.actor, g.actor-box, g.actor-man';

  function play() {
    var lib = window.anime;
    if (!lib) { return; }
    var animate = lib.animate;
    var svgUtil = lib.svg;
    var stagger = lib.stagger;

    // anime.js v4's svg.createDrawable expects a CSS selector or a single
    // element — passing it a NodeList/Array fails silently. So we pass the
    // selector string directly. Same goes for animate() targets: selectors
    // are the most reliable form.

    var nodeMatches = document.querySelectorAll(NODE_SEL);
    var edgeMatches = document.querySelectorAll(EDGE_SEL);

    // Pre-hide nodes inline so they don't pop before anime.js takes over.
    for (var i = 0; i < nodeMatches.length; i++) {
      nodeMatches[i].style.opacity = '0';
    }

    var nodeStep = 80;

    if (nodeMatches.length) {
      animate(NODE_SEL, {
        opacity: [0, 1],
        scale:   [0.85, 1],
        duration: 500,
        delay: stagger(nodeStep),
        ease: 'outBack(1.4)',
      });
    }

    if (edgeMatches.length && svgUtil && svgUtil.createDrawable) {
      var edgeStart = nodeMatches.length * nodeStep + 150;
      animate(svgUtil.createDrawable(EDGE_SEL), {
        draw: ['0 0', '0 1'],
        duration: 700,
        delay: stagger(60, { start: edgeStart }),
        ease: 'inOutQuad',
      });
    }
  }

  var s = document.createElementNS(SVG_NS, 'script');
  s.setAttributeNS(XLINK_NS, 'href', ANIME_URL);
  s.setAttribute('href', ANIME_URL);
  s.addEventListener('load', play);
  s.addEventListener('error', function() {
    console.error('inject-animation: anime.js failed to load from ' + ANIME_URL);
  });
  document.documentElement.appendChild(s);
})();
